{
  "items": [
    {
      "name": "Polynomial.monic_X_pow_add_C",
      "module_name": "Mathlib.Algebra.Polynomial.Monic",
      "kind": "theorem",
      "type": "∀ {R : Type u} (a : R) [inst : Semiring R] {n : ℕ}, n ≠ 0 → (Polynomial.X ^ n + Polynomial.C a).Monic"
    },
    {
      "name": "Polynomial.natDegree_X_pow_mul",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Operations",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] [Nontrivial R] {p : Polynomial R} (n : ℕ),\n  p ≠ 0 → (Polynomial.X ^ n * p).natDegree = p.natDegree + n"
    },
    {
      "name": "Polynomial.natDegree_mul_X",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Operations",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] [Nontrivial R] {p : Polynomial R},\n  p ≠ 0 → (p * Polynomial.X).natDegree = p.natDegree + 1"
    },
    {
      "name": "Polynomial.monomial_mul_X",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (n : ℕ) (r : R),\n  (Polynomial.monomial n) r * Polynomial.X = (Polynomial.monomial (n + 1)) r"
    },
    {
      "name": "Polynomial.Monic.natDegree_mul'",
      "module_name": "Mathlib.Algebra.Polynomial.Monic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {p q : Polynomial R}, p.Monic → q ≠ 0 → (p * q).natDegree = p.natDegree + q.natDegree"
    },
    {
      "name": "Polynomial.degree_lt_degree_mul_X",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Operations",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {p : Polynomial R}, p ≠ 0 → p.degree < (p * Polynomial.X).degree"
    },
    {
      "name": "Polynomial.degree_mul_X",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Operations",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] [Nontrivial R] {p : Polynomial R}, (p * Polynomial.X).degree = p.degree + 1"
    },
    {
      "name": "Polynomial.coeff_X_mul",
      "module_name": "Mathlib.Algebra.Polynomial.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R) (n : ℕ), (Polynomial.X * p).coeff (n + 1) = p.coeff n"
    }
  ]
}
